import React, { useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';
import moment from 'moment';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import { Row, Col, Input, Label } from 'reactstrap';
import DownloadButton from 'views/admin/Common/DownloadButton';
import CustomSelect from 'components/CustomSelect';
import constants, { courseStatic, coursesStatic } from 'config/constants';
import { store } from 'index';
import { showToast } from 'actions/admin/auth';
import { fetchPromotionBatchesApi } from 'actions/admin/promotion';
import { fetchPickerCoursesApi } from 'actions/admin/mentorCalls';
import {
  PDF_REPORTS,
  downloadAttendancePdfApi,
  fetchAttendanceAbsenteesApi,
  fetchAttendanceSummaryApi,
} from 'actions/admin/studentAttendanceReport';
import { formResMessage, getGlobalCurrentBatchUtils, getGlobalSchoolUtils } from 'utils/commonFunc';
import {
  ABSENT_FILTERS,
  PERIODS,
  defaultPeriod,
  pdfFileName,
  percent,
  periodLabel,
  periodProblem,
  reportParams,
} from 'utils/attendanceReport';
import EmptyState from 'views/admin/Common/EmptyState';
import { SkeletonRows } from 'views/admin/Common/Loader';
import StatTile from 'views/admin/Common/StatTile';
import colors from 'config/colors';
import { Chip } from 'views/admin/Promotion/components/StatusChip';
import ScrollTable from 'views/admin/Promotion/components/ScrollTable';
import { HeadCell, ReportPaper } from 'views/admin/Common/ReportBits';

const toastError = err => store.dispatch(showToast(formResMessage(err), 'error'));

// green from 90 %, amber from 75 %, red below: how the class is doing at a glance
const attendanceColor = value => (value >= 90 ? '#2e7d32' : value >= 75 ? '#b26a00' : '#c62828');

const className = item => [item.courseName, item.batchName].filter(Boolean).join(' / ');

// Students' attendance for a day, a month or a date range: class-wise present / absent counts, who was absent (with the dates
// and the periods), and each of these as a PDF to print or share - plus the register and one student's own report.
const StudentAttendanceReport = () => {
  const token = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  // a teacher sees only the classes they are assigned to (one at a time); an admin every class and the other batches
  const isTeacher = useSelector(state => state.auth.loggedUserRole) === constants.roles.teacher;
  const employeeId = useSelector(state => state.auth.loggedUserId);

  const [period, setPeriod] = useState(defaultPeriod);
  const [batchId, setBatchId] = useState(() => getGlobalCurrentBatchUtils()?.batchId || 0);
  const [courseId, setCourseId] = useState(0);
  const [filter, setFilter] = useState('ANY');
  const [batches, setBatches] = useState([]);
  const [courses, setCourses] = useState([]);

  const [summary, setSummary] = useState(null);
  const [absentees, setAbsentees] = useState(null);
  const [shown, setShown] = useState(null); // the period and filter the data on screen was fetched for
  const [loading, setLoading] = useState(false);
  const [downloading, setDownloading] = useState('');
  const [openDays, setOpenDays] = useState({}); // classes whose day-wise table is open
  const latest = useRef(0);

  const problem = periodProblem(period);
  const query = () => reportParams({ schoolId, period, batchId, courseId, filter: '' });

  useEffect(() => {
    if (!schoolId || isTeacher) return;
    fetchPromotionBatchesApi({ token, schoolId })
      .then(list => setBatches(list || []))
      .catch(toastError);
  }, [schoolId]);

  // the classes to narrow the report to are those of the chosen batch
  useEffect(() => {
    setCourseId(0);
    setCourses([]);
    if (!schoolId || !batchId) return;
    fetchPickerCoursesApi({ token, isTeacher, employeeId, batchId })
      .then(list => {
        const sorted = [...list].sort((a, b) => a.courseId - b.courseId);
        setCourses(sorted);
        if (isTeacher) setCourseId(sorted[0]?.courseId || 0);
      })
      .catch(toastError);
  }, [schoolId, batchId]);

  // the report follows every choice, like the other reports: a new date, batch, class or absentee filter asks again
  useEffect(() => {
    load();
  }, [period, batchId, courseId, filter]);

  const setPeriodField = (name, value) => setPeriod(prev => ({ ...prev, [name]: value }));

  const load = async () => {
    // a teacher's report is always for one of their classes: wait until it is known
    if (problem || (isTeacher && !courseId)) return;
    const mine = ++latest.current;
    setLoading(true);
    try {
      const [sum, abs] = await Promise.all([
        fetchAttendanceSummaryApi({ token, params: query() }),
        fetchAttendanceAbsenteesApi({ token, params: reportParams({ schoolId, period, batchId, courseId, filter }) }),
      ]);
      if (mine !== latest.current) return;
      setSummary(sum);
      setAbsentees(abs);
      setShown({ period, filter });
      setOpenDays({});
    } catch (err) {
      if (mine === latest.current) toastError(err);
    } finally {
      if (mine === latest.current) setLoading(false);
    }
  };

  const download = async (key, path, base, extra = {}) => {
    if (problem) return;
    setDownloading(key);
    try {
      await downloadAttendancePdfApi({
        token,
        path,
        params: reportParams({ schoolId, period, batchId, courseId, filter: key === 'absentees' ? filter : '' }),
        fileName: pdfFileName(extra.name ? `${base}_${extra.name}` : base, period),
      });
    } catch (err) {
      toastError(err);
    } finally {
      setDownloading('');
    }
  };

  if (!schoolId) {
    return (
      <EmptyState
        icon="fas fa-school"
        title="Select a school first"
        subtitle="The attendance report works on one school at a time."
      />
    );
  }

  const batchOptions = batches.map(el => ({ ...el, label: el.name, value: el.batchId }));
  const courseOptions = courses.map(el => ({ ...el, label: el.name, value: el.courseId }));
  const classes = summary?.classes || [];
  const absentClasses = absentees?.classes || [];

  return (
    <>
      <ReportPaper
        title="Student attendance report"
        intro={
          isTeacher
            ? `Choose the day, month or dates and one of your ${coursesStatic.toLowerCase()}. The report updates by itself. Use the Download buttons for a PDF to print or share.`
            : 'Choose the day, month or dates (and a class if you want one). The report updates by itself. Use the Download buttons for a PDF to print or share.'
        }
        action={
          <>
            <span style={{ fontSize: 12, color: '#7d7d7d', alignSelf: 'center' }}>Download as PDF:</span>
            <DownloadButton
              label="Summary"
              showLoader
              loading={downloading === 'summary'}
              disabled={!!problem || !!downloading}
              onClick={() => download('summary', PDF_REPORTS.summary.path, PDF_REPORTS.summary.file)}
            />
            <DownloadButton
              label="Absentees"
              showLoader
              loading={downloading === 'absentees'}
              disabled={!!problem || !!downloading}
              onClick={() => download('absentees', PDF_REPORTS.absentees.path, PDF_REPORTS.absentees.file)}
            />
            <DownloadButton
              label="Class register"
              showLoader
              loading={downloading === 'register'}
              disabled={!!problem || !!downloading || !courseId || !batchId}
              onClick={() => download('register', PDF_REPORTS.register.path, PDF_REPORTS.register.file)}
            />
          </>
        }>
        <Row>
          <Col md={3} sm={6} className="mb-2">
            <CustomSelect
              label="Period"
              name="type"
              value={period.type}
              usePortal
              onChange={(name, value) => setPeriodField(name, value)}
              options={PERIODS.map(el => ({ ...el }))}
            />
          </Col>
          {period.type === 'DAY' && (
            <Col md={3} sm={6} className="mb-2">
              <Label className="form-label">Date</Label>
              <Input type="date" value={period.date} onChange={e => setPeriodField('date', e.target.value)} />
            </Col>
          )}
          {period.type === 'MONTH' && (
            <Col md={3} sm={6} className="mb-2">
              <Label className="form-label">Month</Label>
              <Input type="month" value={period.month} onChange={e => setPeriodField('month', e.target.value)} />
            </Col>
          )}
          {period.type === 'CUSTOM' && (
            <>
              <Col md={3} sm={6} className="mb-2">
                <Label className="form-label">From</Label>
                <Input type="date" value={period.from} onChange={e => setPeriodField('from', e.target.value)} />
              </Col>
              <Col md={3} sm={6} className="mb-2">
                <Label className="form-label">To</Label>
                <Input type="date" value={period.to} onChange={e => setPeriodField('to', e.target.value)} />
              </Col>
            </>
          )}
        </Row>
        <Row>
          {!isTeacher && (
            <Col md={3} sm={6} className="mb-2">
              <CustomSelect
                label="Batch"
                name="batchId"
                value={batchId}
                usePortal
                onChange={(name, value) => setBatchId(value)}
                options={batchOptions}
              />
            </Col>
          )}
          <Col md={3} sm={6} className="mb-2">
            <CustomSelect
              label={courseStatic}
              name="courseId"
              value={courseId}
              usePortal
              isClearable={!isTeacher}
              placeholder={isTeacher ? `Select ${courseStatic.toLowerCase()}` : `All ${coursesStatic.toLowerCase()}`}
              onChange={(name, value) => setCourseId(value || 0)}
              options={courseOptions}
            />
          </Col>
          <Col md={3} sm={6} className="mb-2">
            <CustomSelect
              label="Absentees to list"
              name="filter"
              value={filter}
              usePortal
              onChange={(name, value) => setFilter(value)}
              options={ABSENT_FILTERS.map(el => ({ ...el }))}
            />
          </Col>
        </Row>
        {problem && <div style={{ color: '#c62828', fontSize: 13, marginBottom: 8 }}>{problem}</div>}
        <div style={{ fontSize: 12, color: '#7d7d7d', marginBottom: 6 }}>
          Note: changing any of these fields shows the new results straight away, both the summary and the list of
          absent students. There is no button to press.
        </div>
        {!courseId && (
          <div style={{ color: '#6b778a', fontSize: 12, marginBottom: 8 }}>
            The register PDF is for one {courseStatic.toLowerCase()}: choose a {courseStatic.toLowerCase()} to enable
            it.
          </div>
        )}
      </ReportPaper>

      {loading && !summary && (
        <ReportPaper title="Loading the report">
          <SkeletonRows rows={4} avatar={false} />
        </ReportPaper>
      )}

      {summary && (
        <>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 16 }}>
            <StatTile label="Present" value={summary.present ?? 0} tone="good" />
            <StatTile label="Partial absent" value={summary.partialAbsent ?? 0} tone="warn" />
            <StatTile label="Full-day absent" value={summary.fullDayAbsent ?? 0} tone="bad" />
            <StatTile label="Not marked" value={summary.notMarked ?? 0} />
          </div>
          <ReportPaper
            title={`Attendance: ${periodLabel(shown?.period || period)}`}
            intro="Student-days: one student on one day counts once.">
            {!classes.length ? (
              <EmptyState compact bare icon="far fa-folder-open" title="No attendance records found for this period." />
            ) : (
              <ScrollTable maxHeight={480}>
                <Table size="small" stickyHeader>
                  <TableHead>
                    <TableRow>
                      <HeadCell>{courseStatic}</HeadCell>
                      <HeadCell align="right">Students</HeadCell>
                      <HeadCell align="right">With absence</HeadCell>
                      <HeadCell align="right">Present</HeadCell>
                      <HeadCell align="right">Partial</HeadCell>
                      <HeadCell align="right">Full-day absent</HeadCell>
                      <HeadCell align="right">Not marked</HeadCell>
                      <HeadCell align="right">Attendance</HeadCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {classes.map(item => {
                      const key = `${item.courseId}-${item.batchId}-${className(item)}`;
                      const open = !!openDays[key];
                      const hasDaily = !!item.daily?.length;
                      return (
                        <React.Fragment key={key}>
                          <TableRow hover>
                            <TableCell style={{ fontWeight: 'bold', whiteSpace: 'nowrap' }}>
                              {className(item)}
                              {hasDaily && (
                                <a
                                  style={{
                                    marginLeft: 8,
                                    fontWeight: 'normal',
                                    fontSize: 12,
                                    cursor: 'pointer',
                                    color: colors.aTag,
                                  }}
                                  onClick={() => setOpenDays(prev => ({ ...prev, [key]: !prev[key] }))}>
                                  {open ? 'Hide day-wise' : 'Day-wise'}
                                </a>
                              )}
                            </TableCell>
                            <TableCell align="right">{item.totalStudents}</TableCell>
                            <TableCell align="right">{item.studentsWithAbsence}</TableCell>
                            <TableCell align="right">{item.present}</TableCell>
                            <TableCell align="right">{item.partialAbsent}</TableCell>
                            <TableCell align="right">{item.fullDayAbsent}</TableCell>
                            <TableCell align="right">{item.notMarked}</TableCell>
                            <TableCell align="right">
                              <div
                                style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: 8 }}>
                                <div style={{ width: 60, height: 6, borderRadius: 3, background: '#eceff1' }}>
                                  <div
                                    style={{
                                      width: `${Math.min(100, item.attendancePercentage || 0)}%`,
                                      height: 6,
                                      borderRadius: 3,
                                      background: attendanceColor(item.attendancePercentage),
                                    }}
                                  />
                                </div>
                                <b style={{ color: attendanceColor(item.attendancePercentage) }}>
                                  {percent(item.attendancePercentage)}
                                </b>
                              </div>
                            </TableCell>
                          </TableRow>
                          {open && (
                            <TableRow>
                              <TableCell colSpan={8} style={{ background: '#fafbfc' }}>
                                <Table size="small">
                                  <TableHead>
                                    <TableRow>
                                      <HeadCell>Date</HeadCell>
                                      <HeadCell align="right">Present</HeadCell>
                                      <HeadCell align="right">Partial</HeadCell>
                                      <HeadCell align="right">Full-day absent</HeadCell>
                                      <HeadCell align="right">Not marked</HeadCell>
                                    </TableRow>
                                  </TableHead>
                                  <TableBody>
                                    {item.daily.map(day => (
                                      <TableRow key={day.date}>
                                        <TableCell>{moment(day.date).format('ddd, DD MMM YYYY')}</TableCell>
                                        <TableCell align="right">{day.present}</TableCell>
                                        <TableCell align="right">{day.partialAbsent}</TableCell>
                                        <TableCell align="right">{day.fullDayAbsent}</TableCell>
                                        <TableCell align="right">{day.notMarked}</TableCell>
                                      </TableRow>
                                    ))}
                                  </TableBody>
                                </Table>
                              </TableCell>
                            </TableRow>
                          )}
                        </React.Fragment>
                      );
                    })}
                  </TableBody>
                </Table>
              </ScrollTable>
            )}
          </ReportPaper>
        </>
      )}

      {absentees && (
        <ReportPaper
          title={`Absent students: ${absentees.totalAbsentStudents ?? 0}`}
          intro={`${
            ABSENT_FILTERS.find(el => el.value === (shown?.filter || filter))?.label || ''
          }. Each student's own PDF is on the right.`}>
          {!absentClasses.length ? (
            <EmptyState compact bare icon="far fa-user-check" title="No absentees found for this period." />
          ) : (
            absentClasses.map(item => (
              <div key={`${item.courseId}-${item.batchId}-${className(item)}`} style={{ marginBottom: 16 }}>
                <div style={{ fontWeight: 'bold', marginBottom: 4 }}>
                  {className(item)} <span style={{ color: '#8b95a1' }}>({item.absentStudentCount})</span>
                </div>
                <ScrollTable maxHeight={360}>
                  <Table size="small" stickyHeader>
                    <TableHead>
                      <TableRow>
                        <HeadCell>Reg No</HeadCell>
                        <HeadCell>Name</HeadCell>
                        <HeadCell align="right">Full days</HeadCell>
                        <HeadCell align="right">Partial days</HeadCell>
                        <HeadCell>Dates</HeadCell>
                        <HeadCell align="right">PDF</HeadCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {item.students.map(student => (
                        <TableRow key={student.studentId ?? student.registerNumber} hover>
                          <TableCell>{student.registerNumber || '--'}</TableCell>
                          <TableCell style={{ fontWeight: 'bold' }}>{student.studentName}</TableCell>
                          <TableCell align="right">{student.fullDayAbsentDays}</TableCell>
                          <TableCell align="right">{student.partialAbsentDays}</TableCell>
                          <TableCell>
                            {(student.days || []).map(day => (
                              <div key={day.date} style={{ fontSize: 13 }}>
                                <Chip
                                  label={moment(day.date).format('DD MMM')}
                                  tone={day.status === 'FULL_DAY_ABSENT' ? 'bad' : 'warn'}
                                />
                                {!!day.absentPeriods?.length && (
                                  <span style={{ color: '#6b778a' }}> P{day.absentPeriods.join(', ')}</span>
                                )}
                                {day.reason && <span style={{ color: '#6b778a' }}> - {day.reason}</span>}
                              </div>
                            ))}
                          </TableCell>
                          <TableCell align="right">
                            {student.studentId && (
                              <DownloadButton
                                label="Download"
                                showLoader
                                loading={downloading === `student-${student.studentId}`}
                                disabled={!!downloading}
                                onClick={() =>
                                  download(
                                    `student-${student.studentId}`,
                                    `pdf/student/${student.studentId}`,
                                    'Attendance',
                                    { name: String(student.studentName || student.studentId).replace(/\s+/g, '_') }
                                  )
                                }
                              />
                            )}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </ScrollTable>
              </div>
            ))
          )}
        </ReportPaper>
      )}
    </>
  );
};

// Admins (school admin, super admin) see every class of the school; a teacher sees only the classes they are assigned to.
const StudentAttendanceReportPage = () => {
  const loggedUserRole = useSelector(state => state.auth.loggedUserRole);
  if (![constants.roles.admin, constants.roles.SA, constants.roles.teacher].includes(loggedUserRole)) {
    return (
      <EmptyState
        icon="fas fa-lock"
        title="Not available for your role"
        subtitle="The attendance report is for teachers and admins."
      />
    );
  }
  return <StudentAttendanceReport />;
};

export default StudentAttendanceReportPage;
