import axios from 'axios';
import constants from '../../config/constants';

// Student attendance report: class-wise present / absent counts and the names of the absentees, for a day, a month or a
// date range. Each report comes as data (shown on the page) and as a PDF (summary, absentees, register, one student).
const BASE = `${constants.API_BASE_URL}/api/student/attendance-report`;

export const PDF_REPORTS = {
  summary: { path: 'pdf/summary', file: 'Attendance_Summary' },
  absentees: { path: 'pdf/absentees', file: 'Absent_Students' },
  register: { path: 'pdf/register', file: 'Attendance_Register' },
};

export const fetchAttendanceSummaryApi = ({ token, params }) =>
  axios.get(`${BASE}/summary${constants.makeParams(params)}`, constants.setHeader(token)).then(res => res.data);

export const fetchAttendanceAbsenteesApi = ({ token, params }) =>
  axios.get(`${BASE}/absentees${constants.makeParams(params)}`, constants.setHeader(token)).then(res => res.data);

// A PDF comes back as bytes: on an error the message is inside those bytes, so decode it for the toast.
const readableError = err => {
  const data = err?.response?.data;
  if (data instanceof ArrayBuffer) {
    try {
      err.response.data = JSON.parse(new TextDecoder('utf-8').decode(data));
    } catch {
      err.response.data = null;
    }
  }
  return err;
};

// path: 'pdf/summary' | 'pdf/absentees' | 'pdf/register' | `pdf/student/${studentId}`. Saves the file; resolves once it is saved.
export const downloadAttendancePdfApi = async ({ token, path, params, fileName }) => {
  try {
    const res = await axios.get(`${BASE}/${path}${constants.makeParams(params)}`, {
      headers: constants.setHeader(token).headers,
      responseType: 'arraybuffer',
    });
    const url = window.URL.createObjectURL(new Blob([res.data], { type: 'application/pdf' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `${fileName}.pdf`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.URL.revokeObjectURL(url);
  } catch (err) {
    throw readableError(err);
  }
};
