import React from 'react';
import { useSelector } from 'react-redux';
import { Redirect } from 'react-router-dom';
import constants from 'config/constants';
import FinanceReportPage from './FinanceReportPage.jsx';
import CommonReportsPage from './CommonReportsPage.jsx';
import UnofficialReportPage from './UnofficialReportPage.jsx';
import StudentAttendanceReportPage from './StudentAttendanceReportPage.jsx';
import MentorCallsReportPage from './MentorCallsReportPage.jsx';
import TransportReportPage from '../Transport/reports/TransportReportPage.jsx';

// Each kind of report has its own sidebar page under Reports (they used to be tabs of one Reports page).
// Finance, Transport and Unofficial sit in the standard page frame (`content`: the padding every other page has); the
// Common reports page already draws its own.
export const FinanceReportsRoute = () => (
  <div className="content">
    <FinanceReportPage />
  </div>
);
export const TransportReportsRoute = () => (
  <div className="content">
    <TransportReportPage />
  </div>
);
export const UnofficialReportsRoute = () => (
  <div className="content">
    <UnofficialReportPage />
  </div>
);
export const StudentAttendanceReportsRoute = () => (
  <div className="content">
    <StudentAttendanceReportPage />
  </div>
);
export const MentorCallsReportsRoute = () => (
  <div className="content">
    <MentorCallsReportPage />
  </div>
);
export const CommonReportsRoute = CommonReportsPage;

// Query tokens the Common reports page uses for its own inner tabs; an old link carrying one lands on Common.
const COMMON_TAB_QUERIES = [
  'common-report',
  'school-report',
  'batch-course-students-reports',
  'student-report',
  'employee-report',
];

// The old single Reports page (bookmarks, "?transport-report" links): sends each to the page that tab became.
export const LegacyReportsRedirect = ({ location }) => {
  const role = useSelector(state => state.auth.loggedUserRole);
  const search = location?.search || '';
  if (search.includes('transport-report')) return <Redirect to="/admin/reports/transport" />;
  if (search.includes('unofficial-report')) return <Redirect to="/admin/reports/unofficial" />;
  if (COMMON_TAB_QUERIES.some(query => search.includes(query))) {
    return <Redirect to={`/admin/reports/common${search}`} />;
  }
  const canSeeFinance = role === constants.roles.SA || role === constants.roles.admin;
  return <Redirect to={canSeeFinance ? '/admin/reports/finance' : '/admin/reports/common'} />;
};
