import moment from 'moment';

// Pure helpers of the student attendance report page (views/admin/Reports/StudentAttendanceReportPage).

export const PERIODS = [
  { value: 'DAY', label: 'Day' },
  { value: 'MONTH', label: 'Month' },
  { value: 'CUSTOM', label: 'Date range' },
];

export const ABSENT_FILTERS = [
  { value: 'ANY', label: 'All absentees' },
  { value: 'FULL_DAY', label: 'Full day only' },
  { value: 'PARTIAL', label: 'Partial only' },
];

export const todayIso = () => moment().format('YYYY-MM-DD');

export const defaultPeriod = () => ({
  type: 'DAY',
  date: todayIso(),
  month: moment().format('YYYY-MM'),
  from: moment().startOf('month').format('YYYY-MM-DD'),
  to: todayIso(),
});

// What is missing before a report can be asked for, or '' when it is ready.
export const periodProblem = ({ type, date, month, from, to }) => {
  if (type === 'DAY' && !date) return 'Pick the date.';
  if (type === 'MONTH' && !month) return 'Pick the month.';
  if (type === 'CUSTOM') {
    if (!from || !to) return 'Pick both the from and the to date.';
    if (from > to) return 'The from date is after the to date.';
  }
  return '';
};

// The query of every report call: the school, the period, and the optional batch / class (and the absentee filter).
export const reportParams = ({ schoolId, period, batchId, courseId, filter }) => {
  const { type } = period;
  return {
    schoolId,
    type,
    ...(batchId && { batchId }),
    ...(courseId && { courseId }),
    ...(type === 'DAY' && { date: period.date }),
    ...(type === 'MONTH' && { month: period.month }),
    ...(type === 'CUSTOM' && { from: period.from, to: period.to }),
    ...(filter && { filter }),
  };
};

// "11 Nov 2026", "Nov 2026" or "01 Nov 2026 to 11 Nov 2026" - for the file name and the page's heading.
export const periodLabel = ({ type, date, month, from, to }) => {
  if (type === 'MONTH') return moment(month, 'YYYY-MM').format('MMM YYYY');
  if (type === 'CUSTOM') return `${moment(from).format('DD MMM YYYY')} to ${moment(to).format('DD MMM YYYY')}`;
  return moment(date).format('DD MMM YYYY');
};

// Absent_Students_11_Nov_2026 - the same name the backend gives its PDF.
export const pdfFileName = (base, period) => `${base}_${periodLabel(period).replace(/\s+/g, '_')}`;

// "92.5" -> "92.5%"; a missing value shows as a dash.
export const percent = value => (value === null || value === undefined || value === '' ? '--' : `${value}%`);
