import React, { useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import { Row, Col, Input, Label } from 'reactstrap';
import CustomSelect from 'components/CustomSelect';
import constants, { courseStatic, coursesStatic, formStudentName } from 'config/constants';
import { store } from 'index';
import { showToast } from 'actions/admin/auth';
import { fetchMentorCallReportApi, fetchMentorCallSummaryApi } from 'actions/admin/mentorCalls';
import { fetchCourseStudentsApi, fetchPickerCoursesApi } from 'actions/admin/mentorCalls';
import { formResMessage, getGlobalCurrentBatchUtils, getGlobalSchoolUtils } from 'utils/commonFunc';
import {
  CALL_STATUSES,
  PERIODS,
  QUERY_STATUSES,
  callStatusLabel,
  callStatusTone,
  defaultPeriod,
  guardianLine,
  periodProblem,
  queryStatusLabel,
  queryStatusTone,
  rangeLabel,
  reportParams,
  summaryParams,
} from 'utils/mentorCalls';
import ClampedText from 'views/admin/Common/ClampedText';
import EmptyState from 'views/admin/Common/EmptyState';
import { SkeletonRows } from 'views/admin/Common/Loader';
import StatTile from 'views/admin/Common/StatTile';
import { Chip } from 'views/admin/Promotion/components/StatusChip';
import ScrollTable from 'views/admin/Promotion/components/ScrollTable';
import { HeadCell, Pager, ReportPaper } from 'views/admin/Common/ReportBits';

const PAGE_SIZE = 20;
const toastError = err => {
  const detail = err?.response?.data?.detail;
  store.dispatch(showToast(typeof detail === 'string' && detail ? detail : formResMessage(err), 'error'));
};

const outcomeOptions = Object.keys(CALL_STATUSES).map(value => ({ value, label: CALL_STATUSES[value].label }));
const queryOptions = Object.keys(QUERY_STATUSES).map(value => ({ value, label: QUERY_STATUSES[value].label }));

// Mentor calls: the teachers call the guardians of their mentees from the mobile app and note how it went. This is the school's
// view: per-teacher counts (calls, reached, not reachable, call back later, pending, open queries) and every call with its
// feedback, the guardian's query and the follow-up date. A teacher sees only their own calls, an admin everyone's.
const MentorCallsReport = () => {
  const token = useSelector(state => state.auth.loggedUserToken);
  const role = useSelector(state => state.auth.loggedUserRole);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const batchId = getGlobalCurrentBatchUtils()?.batchId || 0;
  const isTeacher = role === constants.roles.teacher;
  const employeeId = useSelector(state => state.auth.loggedUserId);

  const [period, setPeriod] = useState(defaultPeriod);
  const [filters, setFilters] = useState({});
  const [courses, setCourses] = useState([]);
  const [students, setStudents] = useState([]);

  const [summary, setSummary] = useState(null);
  const [report, setReport] = useState(null);
  const [loading, setLoading] = useState(false);
  const latest = useRef(0);

  const problem = periodProblem(period);
  const setPeriodField = (name, value) => setPeriod(prev => ({ ...prev, [name]: value }));
  const setFilter = (name, value) => setFilters(prev => ({ ...prev, [name]: value || undefined }));

  useEffect(() => {
    if (!schoolId || !batchId) return;
    // a teacher picks from the classes they are assigned to, an admin from every class
    fetchPickerCoursesApi({ token, isTeacher, employeeId, batchId })
      .then(list => setCourses([...list].sort((a, b) => a.courseId - b.courseId)))
      .catch(() => {});
  }, [schoolId, batchId]);

  // the student filter is the students of the chosen class
  useEffect(() => {
    setStudents([]);
    if (!filters.courseId) return;
    fetchCourseStudentsApi({ token, courseId: filters.courseId, batchId })
      .then(setStudents)
      .catch(() => {});
  }, [filters.courseId]);

  const load = async ({ page = 1, nextFilters = filters, withSummary = true } = {}) => {
    if (problem) return;
    const mine = ++latest.current;
    setLoading(true);
    try {
      const [sum, rep] = await Promise.all([
        withSummary ? fetchMentorCallSummaryApi({ token, params: summaryParams({ schoolId, period }) }) : summary,
        fetchMentorCallReportApi({
          token,
          params: reportParams({ schoolId, period, filters: nextFilters, page, size: PAGE_SIZE }),
        }),
      ]);
      if (mine !== latest.current) return;
      setSummary(sum);
      setReport(rep);
    } catch (err) {
      if (mine === latest.current) toastError(err);
    } finally {
      if (mine === latest.current) setLoading(false);
    }
  };

  // the report follows every choice, like the other reports (the student id waits until typing stops)
  useEffect(() => {
    const timer = setTimeout(() => load(), 0);
    return () => clearTimeout(timer);
  }, [period, filters.courseId, filters.callStatus, filters.queryStatus, filters.studentId]);

  // clicking a teacher's row narrows the call list to that teacher (and the counts stay for everyone)
  const pickTeacher = employeeId => {
    const next = { ...filters, employeeId: filters.employeeId === employeeId ? undefined : employeeId };
    setFilters(next);
    load({ nextFilters: next, withSummary: false });
  };

  if (!schoolId) {
    return (
      <EmptyState
        icon="fas fa-school"
        title="Select a school first"
        subtitle="Mentor calls work on one school at a time."
      />
    );
  }

  const courseOptions = courses.map(el => ({ ...el, label: el.name, value: el.courseId }));
  const teachers = summary?.teachers || [];
  const items = report?.items || [];

  return (
    <>
      <ReportPaper
        title="Mentor calls report"
        intro="The calls made to guardians, with what they said, their questions and the follow-ups. Choose a period or a filter and the report updates by itself.">
        <Row>
          <Col md={3} sm={6} className="mb-2">
            <CustomSelect
              label="Period"
              name="type"
              value={period.type}
              usePortal
              onChange={(name, value) => setPeriodField(name, value)}
              options={PERIODS.map(el => ({ ...el }))}
            />
          </Col>
          {(period.type === 'DAY' || period.type === 'WEEK') && (
            <Col md={3} sm={6} className="mb-2">
              <Label className="form-label">{period.type === 'WEEK' ? 'Any date in the week' : 'Date'}</Label>
              <Input type="date" value={period.date} onChange={e => setPeriodField('date', e.target.value)} />
            </Col>
          )}
          {period.type === 'MONTH' && (
            <Col md={3} sm={6} className="mb-2">
              <Label className="form-label">Month</Label>
              <Input type="month" value={period.month} onChange={e => setPeriodField('month', e.target.value)} />
            </Col>
          )}
          {period.type === 'YEAR' && (
            <Col md={3} sm={6} className="mb-2">
              <Label className="form-label">Year</Label>
              <Input
                type="number"
                value={period.year}
                onChange={e => setPeriodField('year', e.target.value)}
                style={{ maxWidth: 120 }}
              />
            </Col>
          )}
          {period.type === 'CUSTOM' && (
            <>
              <Col md={3} sm={6} className="mb-2">
                <Label className="form-label">From</Label>
                <Input type="date" value={period.from} onChange={e => setPeriodField('from', e.target.value)} />
              </Col>
              <Col md={3} sm={6} className="mb-2">
                <Label className="form-label">To</Label>
                <Input type="date" value={period.to} onChange={e => setPeriodField('to', e.target.value)} />
              </Col>
            </>
          )}
        </Row>
        <Row>
          <Col md={3} sm={6} className="mb-2">
            <CustomSelect
              label={courseStatic}
              name="courseId"
              value={filters.courseId || 0}
              usePortal
              isClearable
              placeholder={`All ${coursesStatic.toLowerCase()}`}
              onChange={(name, value) =>
                setFilters(prev => ({ ...prev, courseId: value || undefined, studentId: undefined }))
              }
              options={courseOptions}
            />
          </Col>
          <Col md={3} sm={6} className="mb-2">
            <CustomSelect
              label="Outcome"
              name="callStatus"
              value={filters.callStatus || ''}
              usePortal
              isClearable
              placeholder="All outcomes"
              onChange={(name, value) => setFilter(name, value)}
              options={outcomeOptions}
            />
          </Col>
          <Col md={3} sm={6} className="mb-2">
            <CustomSelect
              label="Guardian's question"
              name="queryStatus"
              value={filters.queryStatus || ''}
              usePortal
              isClearable
              placeholder="All"
              onChange={(name, value) => setFilter(name, value)}
              options={queryOptions}
            />
          </Col>
          <Col md={3} sm={6} className="mb-2">
            <CustomSelect
              label="Student"
              name="studentId"
              value={filters.studentId || 0}
              usePortal
              isClearable
              disabled={!filters.courseId}
              placeholder={filters.courseId ? 'All students' : 'Choose a class first'}
              onChange={(name, value) => setFilter(name, value)}
              options={students.map(el => ({
                label: `${formStudentName(el)} (${el.registerNumber})`,
                value: el.studentId,
              }))}
            />
          </Col>
        </Row>
        {problem && <div style={{ color: '#c62828', fontSize: 13, marginBottom: 8 }}>{problem}</div>}
        <div style={{ fontSize: 12, color: '#7d7d7d', marginTop: 4 }}>
          Note: changing any of these fields shows the new results straight away, both the counts per teacher and the
          call list. There is no button to press.
        </div>
      </ReportPaper>

      {loading && !summary && (
        <ReportPaper title="Loading the report">
          <SkeletonRows rows={4} avatar={false} />
        </ReportPaper>
      )}

      {summary && (
        <>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 16 }}>
            <StatTile label="Total calls" value={summary.total ?? 0} />
            <StatTile label="Spoke to guardian" value={summary.connected ?? 0} tone="good" />
            <StatTile label="Could not reach" value={summary.notReachable ?? 0} tone="bad" />
            <StatTile label="Call back later" value={summary.callBackLater ?? 0} tone="warn" />
            <StatTile label="Not called yet" value={summary.pending ?? 0} />
            <StatTile
              label="Questions not answered"
              value={summary.openQueries ?? 0}
              tone={summary.openQueries ? 'bad' : 'good'}
            />
          </div>
          <ReportPaper
            title={`Calls: ${rangeLabel(summary.from, summary.to)}`}
            intro={
              (isTeacher ? 'Your calls. ' : 'Click a teacher to see only their calls below. ') +
              (filters.courseId
                ? 'The counts are for all classes; the call list below shows only the class or student you chose.'
                : '')
            }>
            {!teachers.length ? (
              <EmptyState compact bare icon="far fa-folder-open" title="No calls in this period." />
            ) : (
              <ScrollTable maxHeight={360}>
                <Table size="small" stickyHeader>
                  <TableHead>
                    <TableRow>
                      <HeadCell>Teacher</HeadCell>
                      <HeadCell align="right">Total</HeadCell>
                      <HeadCell align="right">Connected</HeadCell>
                      <HeadCell align="right">Not reachable</HeadCell>
                      <HeadCell align="right">Call back later</HeadCell>
                      <HeadCell align="right">Pending</HeadCell>
                      <HeadCell align="right">Open queries</HeadCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {teachers.map(teacher => (
                      <TableRow
                        key={teacher.employeeId}
                        hover
                        selected={filters.employeeId === teacher.employeeId}
                        style={{ cursor: isTeacher ? 'default' : 'pointer' }}
                        onClick={() => !isTeacher && pickTeacher(teacher.employeeId)}>
                        <TableCell style={{ fontWeight: 'bold' }}>
                          {teacher.teacherName || `Staff #${teacher.employeeId}`}
                        </TableCell>
                        <TableCell align="right">{teacher.total}</TableCell>
                        <TableCell align="right" style={{ color: '#2e7d32', fontWeight: 'bold' }}>
                          {teacher.connected}
                        </TableCell>
                        <TableCell align="right">{teacher.notReachable}</TableCell>
                        <TableCell align="right">{teacher.callBackLater}</TableCell>
                        <TableCell align="right">{teacher.pending}</TableCell>
                        <TableCell
                          align="right"
                          style={{ color: teacher.openQueries ? '#c62828' : undefined, fontWeight: 'bold' }}>
                          {teacher.openQueries}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </ScrollTable>
            )}
          </ReportPaper>
        </>
      )}

      {report && (
        <ReportPaper
          title={`Call list: ${report.totalElements ?? 0}`}
          intro={
            filters.employeeId ? 'Only the teacher chosen above. Click the teacher again to see everyone.' : undefined
          }>
          {!items.length ? (
            <EmptyState compact bare icon="far fa-folder-open" title="No calls match these filters." />
          ) : (
            <ScrollTable maxHeight={520}>
              <Table size="small" stickyHeader>
                <TableHead>
                  <TableRow>
                    <HeadCell>Date</HeadCell>
                    <HeadCell>Teacher</HeadCell>
                    <HeadCell>Student</HeadCell>
                    <HeadCell>{courseStatic}</HeadCell>
                    <HeadCell>Guardian</HeadCell>
                    <HeadCell>Outcome</HeadCell>
                    <HeadCell>What the guardian said</HeadCell>
                    <HeadCell>Guardian&apos;s question</HeadCell>
                    <HeadCell>Follow-up</HeadCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {items.map(call => (
                    <TableRow key={call.mentorCallId} hover>
                      <TableCell style={{ whiteSpace: 'nowrap' }}>{call.callDate}</TableCell>
                      <TableCell>{call.teacherName || `Staff #${call.employeeId}`}</TableCell>
                      <TableCell>
                        <b>{call.studentName}</b>
                        <div style={{ fontSize: 12, color: '#8b95a1' }}>{call.registerNumber}</div>
                      </TableCell>
                      <TableCell>{call.courseName}</TableCell>
                      <TableCell>{guardianLine(call) || '--'}</TableCell>
                      <TableCell>
                        <Chip label={callStatusLabel(call.callStatus)} tone={callStatusTone(call.callStatus)} />
                      </TableCell>
                      <TableCell style={{ minWidth: 160, maxWidth: 320 }}>
                        {call.feedback ? <ClampedText text={call.feedback} /> : '--'}
                      </TableCell>
                      <TableCell style={{ minWidth: 160, maxWidth: 320 }}>
                        {call.queries ? (
                          <>
                            <Chip label={queryStatusLabel(call.queryStatus)} tone={queryStatusTone(call.queryStatus)} />
                            <ClampedText text={call.queries} style={{ marginTop: 6 }} />
                            {call.resolution && (
                              <ClampedText
                                text={`Resolved: ${call.resolution}`}
                                style={{ fontSize: 12, color: '#6b778a', marginTop: 2 }}
                              />
                            )}
                          </>
                        ) : (
                          '--'
                        )}
                      </TableCell>
                      <TableCell style={{ whiteSpace: 'nowrap' }}>{call.followUpDate || '--'}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </ScrollTable>
          )}
          {report.totalPages > 1 && (
            <Pager
              from={(report.page - 1) * PAGE_SIZE + 1}
              to={Math.min(report.totalElements, report.page * PAGE_SIZE)}
              total={report.totalElements}
              hasPrev={report.page > 1}
              hasNext={report.page < report.totalPages}
              disabled={loading}
              onPrev={() => load({ page: report.page - 1, withSummary: false })}
              onNext={() => load({ page: report.page + 1, withSummary: false })}
            />
          )}
        </ReportPaper>
      )}
    </>
  );
};

const MentorCallsReportPage = () => {
  const loggedUserRole = useSelector(state => state.auth.loggedUserRole);
  const allowed = [constants.roles.admin, constants.roles.SA, constants.roles.teacher];
  if (!allowed.includes(loggedUserRole)) {
    return (
      <EmptyState
        icon="fas fa-lock"
        title="Not available for your role"
        subtitle="Mentor calls are for teachers and admins."
      />
    );
  }
  return <MentorCallsReport />;
};

export default MentorCallsReportPage;
