import React from 'react';
import GetAppIcon from '@material-ui/icons/GetApp';
import CustomButton from 'components/CustomButton';

// A download button: the download arrow in front of the label, so nobody has to guess that it saves a file. The same small outlined
// button as "Export Excel" on the other reports.
const DownloadButton = ({ label, size = 'small', ...props }) => (
  <CustomButton
    size={size}
    variant="outlined"
    name={
      <>
        <GetAppIcon style={{ fontSize: 16, marginRight: 4, verticalAlign: 'text-bottom' }} />
        {label}
      </>
    }
    {...props}
  />
);

export default DownloadButton;
